import React,{useEffect,useMemo,useState,useRef} from 'react';
import {createClient} from '@supabase/supabase-js';
import {Home,Compass,Flame,Users,MessageCircle,ThumbsUp,ThumbsDown,Plus,Image as ImageIcon,Search,Bell,ChevronDown,Settings,LogOut,X,ArrowUpRight,ShieldAlert,Menu,Check,Heart,Camera,UploadCloud,Send,RefreshCw,Newspaper,UserPlus,UserCheck,Zap,Lock,Globe,Palette} from 'lucide-react';
