 const feedItems=useMemo(()=>{if(selectedTeam||!['home','friends'].includes(view))return visiblePosts.map(p=>({type:'post',data:p,key:p.id}));const friends=visiblePosts.filter(isFriendPost);const others=visiblePosts.filter(p=>!isFriendPost(p));const postItems=(view==='friends'?friends:[...friends,...others]).map(p=>({type:'post',data:p,key:p.id}));if(view==='friends')return postItems;let pool=news.filter(x=>league==='ALL'||x.league===league).filter(x=>!search||x.title.toLowerCase().includes(search.toLowerCase()));const sample=xs=>[...xs].sort((a,b)=>new Date(b.published_at||0)-new Date(a.published_at||0)).slice(0,12).sort((a,b)=>hashString(a.id+mixSeed)-hashString(b.id+mixSeed));const nflNews=sample(pool.filter(x=>x.league==='NFL'));const collegeNews=sample(pool.filter(x=>x.league==='CFB'));const randomized=[];for(let i=0;i<8;i++){const first=((i+mixSeed)%2===0?nflNews:collegeNews),second=first===nflNews?collegeNews:nflNews;const next=first.shift()||second.shift();if(!next)break;randomized.push(next)}const mixed=[];let n=0;for(let i=0;i<postItems.length;i++){mixed.push(postItems[i]);if((i+1)%3===0&&n<randomized.length)mixed.push({type:'news',data:randomized[n++],key:'news-'+randomized[n-1].id})}while(n<Math.min(randomized.length,postItems.length?2:8))mixed.push({type:'news',data:randomized[n++],key:'news-'+randomized[n-1].id});return mixed},[visiblePosts,selectedTeam,view,news,mixSeed,league,search,friendships,demo.friends,session?.user?.id]);
 function switchTeam(id){setSelectedTeam(id);setView('home');setSidebarOpen(false);const locationUrl=new URL(location.href);if(id)locationUrl.searchParams.set('team',id);else locationUrl.searchParams.delete('team');history.replaceState({},'',locationUrl)}
