 async function submitPost(){if(!newPost.trim()&&!newPhoto)return note('Write something or add a photo first.');if(!getTeam(newTeam))return note('Choose a team.');if(!isMember){setModal('auth');return}setBusy(true);try{let photoUrl=null;let imagePath=null;if(newPhoto){if(connected){imagePath=`${session.user.id}/${crypto.randomUUID()}.${newPhoto.name.split('.').pop()?.toLowerCase()||'jpg'}`;const {error}=await supabase.storage.from('post-images').upload(imagePath,newPhoto,{contentType:newPhoto.type});if(error)throw error}else photoUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(newPhoto)})}if(connected){const {error}=await supabase.from('posts').insert({author_id:session.user.id,team_id:newTeam,body:newPost.trim(),image_path:imagePath});if(error)throw error;await refresh()}else updateDemo(s=>({...s,posts:[{id:crypto.randomUUID(),team_id:newTeam,author:s.profile,body:newPost.trim(),image_url:photoUrl,created_at:new Date().toISOString(),score:0,comments:0},...s.posts]}));setNewPost('');setPreview('');setNewPhoto(null);setModal('');switchTeam(newTeam);note('Your post is live!')}catch(err){note(err.message||'Could not publish post')}finally{setBusy(false)}}
 async function castVote(post,value){if(!isMember){setModal('auth');return}if(connected){const previous=liked(post);if(previous===value){await supabase.from('votes').delete().eq('post_id',post.id).eq('user_id',session.user.id)}else{const {error}=await supabase.from('votes').upsert({post_id:post.id,user_id:session.user.id,value},{onConflict:'post_id,user_id'});if(error)note(error.message)}await refresh()}else updateDemo(s=>{const old=s.votes[post.id]||0;const next=old===value?0:value;return {...s,votes:{...s.votes,[post.id]:next},posts:s.posts.map(p=>p.id===post.id?{...p,score:(p.score||0)+next-old}:p)}})}
