 async function authenticate(e){e.preventDefault();if(!connected){note('Demo mode: add your Supabase keys to enable real accounts.');return}setBusy(true);try{if(authMode==='signup'){const {data,error}=await supabase.auth.signUp({email:authEmail,password:authPassword,options:{data:{display_name:authName.trim()||'New Fan'}}});if(error)throw error;note(data.session?'Account created!':'Check your email to confirm your account.');if(!data.session)setModal('')}else{const {error}=await supabase.auth.signInWithPassword({email:authEmail,password:authPassword});if(error)throw error;note('Welcome back!');setModal('')}}catch(err){note(err.message)}finally{setBusy(false)}}
 function openSettings(){setDraftNFL(effectiveProfile?.favorite_nfl||'');setDraftCFB(effectiveProfile?.favorite_cfb||'');setDraftNFLTeams(effectiveProfile?.favorite_nfl_teams?.length?effectiveProfile.favorite_nfl_teams:(effectiveProfile?.favorite_nfl?[effectiveProfile.favorite_nfl]:[]));setDraftCFBTeams(effectiveProfile?.favorite_cfb_teams?.length?effectiveProfile.favorite_cfb_teams:(effectiveProfile?.favorite_cfb?[effectiveProfile.favorite_cfb]:[]));setDraftName(effectiveProfile?.display_name||'');setDraftPrivacy(effectiveProfile?.profile_visibility||'public');setDraftAllowBlitz(effectiveProfile?.allow_blitz!==false);setModal('settings')}
 async function saveSettings(){setBusy(true);try{if(draftNFLTeams.length===0)throw new Error('Choose at least one NFL team.');if(connected){if(!isMember){setModal('auth');return}if(draftNFLTeams.length===0)throw new Error('Choose at least one NFL team.');const {data,error}=await supabase.from('profiles').update({favorite_nfl:draftNFLTeams.includes(draftNFL)?draftNFL:draftNFLTeams[0],favorite_cfb:draftCFBTeams.includes(draftCFB)?draftCFB:(draftCFBTeams[0]||null),favorite_nfl_teams:draftNFLTeams,favorite_cfb_teams:draftCFBTeams,profile_visibility:draftPrivacy,allow_blitz:draftAllowBlitz,display_name:draftName.trim()||'Football fan'}).eq('id',session.user.id).select().single();if(error)throw error;setProfile(data)}else updateDemo(s=>({...s,profile:{...s.profile,display_name:draftName.trim()||'Football fan',favorite_nfl:draftNFLTeams.includes(draftNFL)?draftNFL:draftNFLTeams[0],favorite_cfb:draftCFBTeams.includes(draftCFB)?draftCFB:draftCFBTeams[0],favorite_nfl_teams:draftNFLTeams,favorite_cfb_teams:draftCFBTeams,profile_visibility:draftPrivacy,allow_blitz:draftAllowBlitz}}));setModal('');note('Favorite teams updated everywhere!')}catch(err){note(err.message)}finally{setBusy(false)}}
