 if(connected&&!session)return <div className="auth-screen"><div className="auth-card"><div className="auth-logo">🏈 <b>LockerNoise</b> <span>WORKING NAME</span></div><h1>{authMode==='signup'?'Join the football conversation':'Welcome back, fan'}</h1><p>Everyone needs a free account to access the community. Choose multiple NFL and college teams after verifying your email.</p><div className="auth-theme"><span>Choose your look</span><ThemeChoices value={theme} onChange={chooseTheme}/></div><form className="auth-form" onSubmit={authenticate}>{authMode==='signup'&&<><label>Display name</label><input className="text-field" value={authName} onChange={e=>setAuthName(e.target.value)} placeholder="Your fan name" maxLength={40} required/></>}<label>Email</label><input className="text-field" type="email" value={authEmail} onChange={e=>setAuthEmail(e.target.value)} required/><label>Password</label><input className="text-field" type="password" minLength={8} value={authPassword} onChange={e=>setAuthPassword(e.target.value)} required/><button className="primary-btn modal-cta" type="submit" disabled={busy}>{busy?'Please wait…':authMode==='signup'?'Create free account':'Sign in'}</button><button type="button" className="switch-auth" onClick={()=>setAuthMode(authMode==='signup'?'signin':'signup')}>{authMode==='signup'?'Already have an account? Sign in':'New fan? Create an account'}</button></form>{feedback&&<p className="auth-notice" role="status">{feedback}</p>}<small>Independent, unofficial sports community. Brand and official team logos pending legal review.</small></div></div>;
